const fn = new Function(code + "\nreturn { reachable };");
const { reachable } = fn();
const cs = { C: "B", B: "A", A: null };
const out = reachable(cs, "C");
if (out.join(",") !== "A,B,C") throw new Error("Oldest-first: root A up to C.");

const fn = new Function(code + "\nreturn { reachable };");
const { reachable } = fn();
const cs = { D: null, E: "D" };
if (reachable(cs, "D").join(",") !== "D") throw new Error("A root reaches only itself.");
if (reachable(cs, "E").join(",") !== "D,E") throw new Error("E reaches D then E.");
